<script setup lang="ts">
import {computed,watch,nextTick} from 'vue'
import {useRoute} from 'vue-router'
import {useTabStore} from '../../store/modules/tab'
import {useGmWorkspace} from '../../stores/gm/useGmWorkspace'
import {useGmWorkspaceBindings} from '../../stores/gm/useGmWorkspace'
import {asyncPanel} from '../../asyncPanel'
import PlayerCenter from '../../components/PlayerCenter.vue'
import LiveSession from '../../components/LiveSession.vue'
import FieldError from '../../components/FieldError.vue'
const {fieldErrors,feedbackScope,busy,error,notice,tab,page,search,rows,account,roleResults,rolePage,roleMode,playerViews,action,currency,delta,reason,message,pendingId,tabs,onlineLabel,money,openCharacter,draft,run,load,go,copyMailDraft,correctOperation,playerAction,refreshAccount,select,loadRoles,queryCharacters,selectRole,makePreview,inspectOperation,accountMode,role,quickAmount,changeDirection,chooseOperation,searchAccounts,toMail}=useGmWorkspaceBindings()

const workspace=useGmWorkspace()
const route=useRoute(),tabStore=useTabStore()
const openedPlayers=computed(()=>Object.values(workspace.players.workspaces))
watch(()=>route.params.uid,async value=>{await workspace.activate('accounts',false);await workspace.run(()=>workspace.setTarget(Number(value),Number(route.query.charac_no)||0));await nextTick();if(workspace.account?.uid===Number(route.params.uid))tabStore.setTabLabel(workspace.account.accountname+' · UID '+workspace.account.uid)},{immediate:true})
</script>
<template><div class="gm-workspace"><nav class="player-workspace-tabs" aria-label="已打开的玩家"><RouterLink v-for="player in openedPlayers" :key="player.uid" :to="'/players/'+player.uid" :class="{active:player.uid===account?.uid}">{{player.account.accountname}} · {{player.uid}}</RouterLink></nav><section v-if="account" class="panel account-workspace" data-testid="account-operations"><div class="account-heading"><div class="avatar large">{{account.accountname?.slice(0,1).toUpperCase()}}</div><div><h2>{{account.accountname}} <span class="pill">UID {{account.uid}}</span></h2><p class="muted">账号级余额与登录权限 · 角色邮件在邮件工作区发放</p></div><button class="ghost" :disabled="busy" @click="refreshAccount">刷新余额</button></div><div class="balance-strip"><div><span>点券</span><strong>{{money(account.cera)}}</strong></div><div><span>代币券</span><strong>{{money(account.cera_point)}}</strong></div><div><span>积分</span><strong>{{money(account.mileage)}}</strong></div><div><span>登录表状态</span><b>{{onlineLabel(account)}}</b></div></div><LiveSession :uid="account.uid" /><button class="ghost" @click="go('native-controls')">管理此账号的游戏内控制</button><div class="operation-tabs" aria-label="账号操作"><button :class="{active:action==='currency'}" :disabled="busy||!!pendingId" @click="chooseOperation('currency')">余额变更</button><button :disabled="busy||!!pendingId" @click="chooseOperation('mail')">发送物品邮件 ↗</button><button :class="{active:action==='ban'||action==='unban'}" :disabled="busy||!!pendingId" @click="chooseOperation('ban')">封禁管理</button></div>
    <div class="form-grid" v-if="action==='currency'"><label>币种<select v-model="currency" :disabled="busy"><option value="cera">点券</option><option value="cera_point">代币券</option><option value="mileage">积分</option></select></label><div class="field"><span class="field-label">变更方向</span><div class="segmented"><button :class="{active:delta>=0}" :disabled="busy" @click="changeDirection(false)">充值 +</button><button :class="{active:delta<0}" :disabled="busy" @click="changeDirection(true)">扣减 −</button></div></div><label><span>变更金额 <em class="required-tag">必填</em></span><input id="operation-delta" v-model.number="delta" type="number" step="1" aria-required="true" :aria-invalid="!!fieldErrors['operation-delta']" :aria-describedby="fieldErrors['operation-delta']?'operation-delta-error':undefined" :disabled="busy"><small>正数充值，负数扣减</small><FieldError id="operation-delta-error" :message="fieldErrors['operation-delta']"/></label><div class="wide quick-amounts"><span>快捷金额</span><button v-for="n in [100,1000,10000,100000]" :key="n" :disabled="busy" @click="quickAmount(n)">{{money(n)}}</button></div></div>
    <div v-else-if="action==='ban'||action==='unban'" class="form-grid"><label>处罚操作<select v-model="action" aria-label="处罚操作" :disabled="busy"><option value="ban">封禁后续登录</option><option value="unban">解除本后台封禁</option></select></label><p class="field-hint wide">不立即踢出在线玩家；不能覆盖或解除其他来源处罚。</p></div>
    <template v-if="action==='currency'||action==='ban'||action==='unban'"><label class="reason-field"><span>操作原因 <em class="required-tag">必填</em></span><input id="operation-reason" v-model="reason" aria-required="true" :aria-invalid="!!fieldErrors['operation-reason']" :aria-describedby="fieldErrors['operation-reason']?'operation-reason-error':undefined" placeholder="必填，写入不可删除审计" maxlength="200" :disabled="busy"><FieldError id="operation-reason-error" :message="fieldErrors['operation-reason']"/><span class="button-row"><button v-for="preset in ['活动奖励','问题补偿','管理员测试','纠正先前操作']" :key="preset" type="button" :disabled="busy||!!pendingId" @click="reason=preset">{{preset}}</button></span></label><p v-if="error&&feedbackScope==='operation'" class="submit-error">{{error}}</p><p v-else-if="notice&&feedbackScope==='operation'" class="submit-success">{{notice}}</p><div class="action-footer"><span class="muted">下一步只生成预览，不会立即写入。</span><button class="primary" :disabled="busy" @click="makePreview">生成预览 →</button></div></template><button v-else class="primary" :disabled="busy" @click="toMail">前往邮件工作区 →</button>
    <PlayerCenter v-if="account" :view-state="playerViews[account.uid]" @view-state="playerViews[account.uid]=$event" :account="account" :busy="busy||!!pendingId" @action="playerAction" @draft="copyMailDraft" @inspect="inspectOperation" @correction="correctOperation" /></section><section v-else class="selection-guide"><h3>先选择一位玩家</h3><p>点击列表中的“管理”，余额变更与封禁操作将在这里展开。</p></section></div></template>
<style scoped>.player-workspace-tabs{display:flex;gap:8px;overflow:auto;padding:4px 0 14px}.player-workspace-tabs a{white-space:nowrap;padding:8px 12px;border-radius:8px;background:var(--bg-primary);border:1px solid var(--border-color)}.player-workspace-tabs a.active{color:var(--primary-color);border-color:var(--primary-color)}</style>